  const { run, gitOps } = useGit();

  const actions = [
    { id: 'commit', act: propose },
    { id: 'pull',   act: () => run('pull', gitOps.pull) },
    { id: 'push',   act: () => run('push', gitOps.push) },
  ];
  return <Actions items={actions} />;
}

